<?php declare(strict_types=1);namespace App\Services;use App\Core\Config;final class StripeService{public static function mode():string{$v=(string)setting('payment.mode',Config::get('payment.mode','sandbox'));if($v==='stripe'&&self::secretKey()===''){return'sandbox';}return in_array($v,['stripe','sandbox','manual'],true)?$v:'sandbox';}public static function secretKey():string{return(string)setting('payment.stripe_secret_key',Config::get('payment.stripe_secret_key',''));}public static function publishableKey():string{return(string)setting('payment.stripe_publishable_key',Config::get('payment.stripe_publishable_key',''));}public static function webhookSecret():string{return(string)setting('payment.stripe_webhook_secret',Config::get('payment.stripe_webhook_secret',''));}public static function request(string $i,string $k,array $m=[],?string $j=null):array{$a=curl_init('https://api.stripe.com/v1/'.ltrim($k,'/'));$K=['Authorization: Bearer '.self::secretKey(),'Stripe-Version: 2024-06-20'];if($j){$K[]='Idempotency-Key: '.$j;}curl_setopt_array($a,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$i,CURLOPT_HTTPHEADER=>$K,CURLOPT_TIMEOUT=>30,CURLOPT_SSL_VERIFYPEER=>true]);if($i==='POST'){curl_setopt($a,CURLOPT_POSTFIELDS,http_build_query($m));}elseif($m){curl_setopt($a,CURLOPT_URL,'https://api.stripe.com/v1/'.ltrim($k,'/').'?'.http_build_query($m));}$y=curl_exec($a);$R=curl_error($a);$p=(int)curl_getinfo($a,CURLINFO_RESPONSE_CODE);curl_close($a);if($y===false){throw new \RuntimeException('Stripe : '.$R);}$q=json_decode((string)$y,true);if(!is_array($q)){throw new \RuntimeException('Stripe : réponse invalide');}if($p>=400){throw new \RuntimeException('Stripe : '.($q['error']['message']??'erreur '.$p));}return $q;}public static function createCheckoutSession(array $k,array $C,array $W,string $j):array{$g=rtrim((string)Config::get('app.url'),'/');$e=$W['lang']?:'fr';$H=['mode'=>'payment','client_reference_id'=>(string)$k['id'],'customer_email'=>$W['email'],'success_url'=>$g.'/'.$e.'/checkout/success/'.$k['id'].'?session_id={CHECKOUT_SESSION_ID}','cancel_url'=>$g.'/'.$e.'/checkout/cancel/'.$k['id'],'metadata[order_id]'=>(string)$k['id'],'metadata[plan]'=>$C['slug'],'line_items[0][quantity]'=>'1','line_items[0][price_data][currency]'=>strtolower($k['currency']),'line_items[0][price_data][unit_amount]'=>(string)((int)$k['subtotal']-(int)$k['discount']),'line_items[0][price_data][product_data][name]'=>$j];if((int)$k['tax']>0){$H['line_items[1][quantity]']='1';$H['line_items[1][price_data][currency]']=strtolower($k['currency']);$H['line_items[1][price_data][unit_amount]']=(string)$k['tax'];$H['line_items[1][price_data][product_data][name]']='TVA '.$k['tax_rate'].' %';}if(!empty($W['stripe_customer_id'])){unset($H['customer_email']);$H['customer']=$W['stripe_customer_id'];}$G=self::request('POST','checkout/sessions',$H,'order-'.$k['id'].'-'.substr(md5((string)$k['total']),0,8));return['id'=>$G['id'],'url'=>$G['url']];}public static function retrieveSession(string $q):array{return self::request('GET','checkout/sessions/'.rawurlencode($q));}public static function verifyWebhook(string $n,string $m,?string $i=null,int $d=300):bool{$i=$i??self::webhookSecret();if($i===''){return false;}$e=null;$y=[];foreach(explode(',',$m)as $M){[$k,$c]=array_pad(explode('=',trim($M),2),2,'');if($k==='t'){$e=(int)$c;}elseif($k==='v1'){$y[]=$c;}}if($e===null||!$y||abs(time()-$e)>$d){return false;}$j=hash_hmac('sha256',$e.'.'.$n,$i);foreach($y as $Y){if(hash_equals($j,$Y)){return true;}}return false;}}